const $=s=>document.querySelector(s),content=$('#content');let sessions=[],stream,recorder,chunks=[],timer,started,seconds=0,recognition,transcript='',pending=null,db,activeURL,view='home';
window.addEventListener('DOMContentLoaded',()=>{const emptyStyles=document.createElement('link');emptyStyles.rel='stylesheet';emptyStyles.href='empty-state.css';document.head.appendChild(emptyStyles);const cloudScript=document.createElement('script');cloudScript.src='cloud.js';document.body.appendChild(cloudScript)});
const samples=[{id:'sample-1',title:'The idea that started it all',duration:264,date:'Example session',type:'Pitch practice'},{id:'sample-2',title:'Making the complex feel simple',duration:372,date:'Example session',type:'Product walkthrough'},{id:'sample-3',title:'A story worth sharing',duration:198,date:'Example session',type:'Storytelling'}];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}$('.close').onclick=()=>$('#dialog').close();
function fmt(n){return Math.floor(n/60).toString().padStart(2,'0')+':'+Math.floor(n%60).toString().padStart(2,'0')}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const req=indexedDB.open('stagesight-local-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('sessions',{keyPath:'id'});req.onsuccess=()=>{db=req.result;refresh()};req.onerror=()=>toast('Device storage unavailable. You can still download recordings.');
function refresh(){const r=db.transaction('sessions').objectStore('sessions').getAll();r.onsuccess=()=>{sessions=r.result.sort((a,b)=>b.created-a.created);if(view==='home'||view==='library')render(view)}}
function card(s,i){return `<article class="session" tabindex="0" role="button" data-session="${s.id}" aria-label="Open ${esc(s.title)}"><div class="thumb ${['','second','third'][i%3]}"><div class="abstract"></div><span class="sample-label">${s.blob?'ON THIS DEVICE':'SAMPLE REPORT'}</span><span class="duration">${fmt(s.duration)}</span></div><div class="session-body"><h3>${esc(s.title)}</h3><p>${esc(s.date)} · ${esc(s.type||'Practice session')}</p><div class="session-bottom"><span class="ready">${s.blob?'● Saved locally':'◇ Explore the report'}</span><span>View session ↗</span></div></div></article>`}
function heading(k,title,sub){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">Your next talk starts here ✧</div></div>`}
function stopTracks(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
function render(v){if(recorder?.state==='recording'){toast('Stop and save your recording before leaving.');return}if(view==='studio'&&v!=='studio')stopTracks();view=v;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#crumb').textContent=({home:'Overview',studio:'Practice studio',library:'My sessions',report:'Session report'})[v];if(activeURL){URL.revokeObjectURL(activeURL);activeURL=null}
if(v==='home')content.innerHTML=heading('A LITTLE BETTER, EVERY TIME','Find your voice. Own your stage.','A space to practice, reflect, and grow into your next great presentation.')+`<section class="hero"><div class="hero-copy"><span class="pill">✦ &nbsp; YOUR NEXT CHAPTER STARTS HERE</span><h2>Great presentations<br>begin with practice.</h2><p>Rehearse your talk, see how you deliver, and turn every session into a step forward.</p><div class="actions"><button class="primary" data-view="studio">◉ &nbsp; Start a practice session &nbsp; ↗</button><button class="text-button" id="how">How it works →</button></div></div><div class="stage-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="mic"></div><span class="float-label a">✦ &nbsp; A clearer message</span><span class="float-label b">↗ &nbsp; One rehearsal at a time</span></div></section><div class="stats"><div class="stat"><div class="stat-label">Practice sessions <span>▤</span></div><strong>${sessions.length}</strong><small>Your personal practice journey</small></div><div class="stat"><div class="stat-label">Time well spent <span>◷</span></div><strong>${Math.floor(sessions.reduce((n,s)=>n+s.duration,0)/60)} <span style="font-size:14px;font-weight:500">min</span></strong><small>Invested in your next great talk</small></div><div class="stat"><div class="stat-label">Your next milestone <span>⚑</span></div><strong style="font-size:20px;padding-top:6px">${sessions.length?'Keep the rhythm':'Your first rehearsal'}</strong><small>Progress starts with showing up</small></div></div><div class="section-head"><h2>${sessions.length?'Recent sessions':'A glimpse of your next chapter'}</h2><button class="text-button" data-view="library">View all sessions →</button></div><div class="grid">${(sessions.length?sessions.slice(0,3):samples).map(card).join('')}</div><div class="bottom-grid"><div class="note"><div class="icon">✦</div><div><h3>One thing to try in your next session</h3><p>Give your opening a little breathing room. A purposeful pause lets your first idea land.</p></div></div><div class="note tint"><div class="icon">♧</div><div><h3>Your practice. Your space.</h3><p>Recordings stay in this browser. You decide what to keep and when to delete.</p></div></div></div>`;
if(v==='library')content.innerHTML=heading('YOUR PRACTICE JOURNEY','My sessions','Revisit a rehearsal. Notice what changed. Take the next step.')+`<div class="section-head"><span class="date">${sessions.length} recordings saved on this device</span><button class="primary" data-view="studio">＋ New session</button></div>${sessions.length?`<div class="grid">${sessions.map(card).join('')}</div>`:`<div class="panel empty"><h2>Your story starts here.</h2><p>Your saved practice sessions will appear in this space.</p><button class="primary" data-view="studio">Start your first rehearsal</button></div>`}`;
if(v==='studio'){seconds=0;transcript='';content.innerHTML=heading('THE PRACTICE STUDIO','Take a breath. You’ve got this.','Make room for a rehearsal, without the pressure of an audience.')+`<div class="studio-grid"><div><div class="video-wrap"><video id="preview" autoplay muted playsinline></video><div class="video-placeholder"><strong>Your stage is ready.</strong><p>Enable your camera and microphone to get started.</p></div><div class="rec-time" id="clock">○ &nbsp; 00:00</div></div><div class="actions"><button class="secondary" id="enable">Enable camera & microphone</button><button class="primary" id="record" disabled>● Start recording</button><button class="danger" id="stop" disabled>■ Stop & save</button></div><div id="save-state"></div><div class="notice">Saved only in this browser • Download a backup for safekeeping • No automatic cleanup</div><div class="panel"><h3>Live transcript <span class="pill">Browser dependent</span></h3><p style="font-size:11px">If supported, speech recognition may send audio to your browser provider. Opt in before recording.</p><label class="consent"><input type="checkbox" id="speech"> Enable browser speech recognition</label><div id="transcript" class="transcript">Transcript will appear here when enabled and available.</div></div></div><div class="panel"><h3>Set yourself up</h3><label class="field" for="title">Session title</label><input type="text" id="title" maxlength="100" placeholder="e.g. My hackathon pitch"><label class="field" for="type">What are you practicing?</label><select id="type"><option>Pitch practice</option><option>Product walkthrough</option><option>Storytelling</option><option>Keynote</option></select><div class="status-line">Camera & microphone <span id="permission">Not enabled</span></div><div class="status-line">Visual detection <span>Unavailable</span></div><div class="status-line">Live AI coaching <span>Not connected</span></div><label class="consent"><input type="checkbox" id="consent">Everyone who may appear or be heard knows they are being recorded and has agreed.</label><div class="notice">Try a quiet spot with light in front of you. Place your camera at eye level and leave a little space above your head.</div><div class="metrics"><div class="metric"><strong id="pace">—</strong><small>est. words/min</small></div><div class="metric"><strong id="words">—</strong><small>words captured</small></div><div class="metric"><strong id="fillers">—</strong><small>est. fillers</small></div></div><p style="font-size:10px">Measurements use captured transcript words and elapsed time. Speaking time, pauses, and audio energy are unavailable in this version.</p></div></div>`;$('#enable').onclick=enable;$('#consent').onchange=()=>$('#record').disabled=!stream||!$('#consent').checked;$('#record').onclick=start;$('#stop').onclick=stop;}
if(v==='home'&&!sessions.length){
 const sessionGrid=content.querySelector('.grid');
 const sectionHeading=sessionGrid.previousElementSibling.querySelector('h2');
 sectionHeading.textContent='Your recordings';
 sessionGrid.outerHTML=`<section class="panel empty recording-empty"><span class="empty-record-icon" aria-hidden="true">◉</span><h2>No recordings yet</h2><p>Record your first practice session to see it here.</p><button class="primary" data-view="studio">● &nbsp; Start recording</button></section><details class="sample-examples"><summary>Explore example reports <span>Demo content · no real recordings</span></summary><p>These examples show the report layout. The titles, durations, and coaching are illustrative.</p><div class="grid">${samples.map(card).join('')}</div></details>`;
}
bind()}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));document.querySelectorAll('[data-session]').forEach(b=>{b.onclick=()=>report(b.dataset.session);b.onkeydown=e=>{if(e.key==='Enter')b.click()}});if($('#how'))$('#how').onclick=()=>modal('<h2>Practice. Reflect. Repeat.</h2><p>1. Enable your camera and microphone, and confirm consent.</p><p>2. Record your rehearsal. Optionally enable browser transcription.</p><p>3. Save on this device, replay, download, or delete.</p><div class="notice">Cloud accounts, cross-device playback, visual analysis, and AI coaching need service integration.</div>')}
async function enable(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable in this browser. Try a supported browser on HTTPS or localhost.');return}$('#enable').disabled=true;$('#permission').textContent='Requesting…';try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:true});$('#preview').srcObject=stream;$('.video-placeholder').style.display='none';$('#permission').textContent='Enabled';$('#record').disabled=!$('#consent').checked;$('#enable').textContent='✓ Devices enabled'}catch(e){$('#permission').textContent=e.name==='NotAllowedError'?'Permission denied':'Device unavailable';toast(e.name==='NotAllowedError'?'Allow camera and microphone in browser settings, then retry.':'Camera or microphone unavailable. Close other apps using them and retry.');$('#enable').disabled=false;$('#enable').textContent='Retry camera & microphone'}}
function counts(){const words=transcript.trim().split(/\s+/).filter(Boolean);return {words:words.length,fillers:(transcript.match(/\b(um|uh|erm|hmm)\b/gi)||[]).length}}
function start(){try{chunks=[];transcript='';pending=null;recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=save;recorder.onerror=()=>{toast('Recording interrupted. Stopping to preserve collected media.');if(recorder.state!=='inactive')stop()};recorder.start(1000);started=Date.now();$('#record').disabled=true;$('#stop').disabled=false;$('#enable').disabled=true;$('#title').disabled=true;$('#speech').disabled=true;$('#consent').disabled=true;timer=setInterval(()=>{seconds=(Date.now()-started)/1000;$('#clock').textContent='● '+fmt(seconds);const c=counts();$('#pace').textContent=c.words?Math.round(c.words/(seconds/60)):'—';$('#words').textContent=c.words||'—';$('#fillers').textContent=c.words?c.fillers:'—'},500);if($('#speech').checked){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){recognition=new SR();recognition.continuous=true;recognition.interimResults=false;recognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++)transcript+=e.results[i][0].transcript+' ';$('#transcript').textContent=transcript};recognition.onerror=e=>{$('#transcript').textContent=transcript||'Speech recognition unavailable: '+e.error};recognition.start()}else $('#transcript').textContent='Speech recognition is unavailable in this browser.'}}catch(e){clearInterval(timer);toast('Unable to start recording: '+e.message)}}
function stop(){seconds=(Date.now()-started)/1000;clearInterval(timer);recognition?.stop();recognition=null;$('#stop').disabled=true;if(recorder.state!=='inactive')recorder.stop();stopTracks()}
function save(){if(!pending)pending={id:crypto.randomUUID(),title:$('#title').value.trim()||'Untitled rehearsal',type:$('#type').value,date:new Date().toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}),created:Date.now(),duration:seconds,transcript,blob:new Blob(chunks,{type:recorder.mimeType})};if(!pending.blob.size){toast('No video data was captured. Please try another recording.');return}$('#save-state').innerHTML='<p>Saving recording on this device…</p>';try{if(!db)throw Error('Storage unavailable');const tx=db.transaction('sessions','readwrite');tx.objectStore('sessions').put(pending);tx.oncomplete=()=>{sessions.unshift(pending);const id=pending.id;pending=null;toast('Recording saved on this device.');report(id)};tx.onerror=failed;tx.onabort=failed}catch(e){failed()}}
function failed(){$('#save-state').innerHTML='<div class="notice">Save failed. Your recording is still available in this tab. Keep this tab open.</div><button class="secondary" id="retry">Retry save</button> <button class="secondary" id="backup">Download recording</button>';$('#retry').onclick=save;$('#backup').onclick=()=>download(pending)}
function download(s){const u=URL.createObjectURL(s.blob),a=document.createElement('a');a.href=u;a.download='stagesight-'+s.id+(s.blob.type.includes('mp4')?'.mp4':'.webm');a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function report(id){const s=[...sessions,...samples].find(x=>x.id===id);if(!s)return;render('report');const sample=!s.blob;const words=(s.transcript||'').trim().split(/\s+/).filter(Boolean).length;content.innerHTML=heading(sample?'ILLUSTRATIVE SAMPLE · NO RECORDING':'YOUR SESSION REPLAY',esc(s.title),sample?'Explore the report layout. These observations are examples.':`${esc(s.date)} · ${fmt(s.duration)} · Saved on this device`)+`<div class="tabs"><button class="active">Session overview</button><button id="transcript-tab">Jump to transcript ↓</button></div><div class="report-grid"><div><div class="video-wrap">${sample?'<div class="video-placeholder"><strong>A place to see your progress.</strong><p>This sample has no recorded video or measured results.</p></div>':'<video id="playback" controls playsinline></video>'}</div><div class="metrics"><div class="metric"><strong>${words?Math.round(words/(s.duration/60)):'—'}</strong><small>est. words/min</small></div><div class="metric"><strong>${words||'—'}</strong><small>words captured</small></div><div class="metric"><strong>${fmt(s.duration)}</strong><small>session duration</small></div></div><div class="panel" style="margin-top:20px" id="report-transcript"><h3>Transcript</h3><p>${esc(s.transcript||'Unavailable. No transcript was captured for this session.')}</p></div></div><div><div class="panel"><span class="pill">${sample?'EXAMPLE COACHING':'SESSION STATUS'}</span><h3>${sample?'Give your ideas room to land.':'A rehearsal worth returning to.'}</h3><p>${sample?'Try a short pause after your key message. Keep your opening focused on one clear idea, and finish with a specific next step.':'Replay your recording to reflect on your opening, transitions, and closing. Automated coaching is unavailable until the AI service is connected.'}</p><div class="status-line">Video <span>${sample?'Sample only':'Saved locally'}</span></div><div class="status-line">Transcript <span>${words?'Captured':'Unavailable'}</span></div><div class="status-line">Visual observations <span>Unavailable</span></div><div class="status-line">AI report <span>Not connected</span></div><div class="status-line">Pauses & audio energy <span>Unavailable</span></div><p style="font-size:10px">No delivery score or timestamped review moments are generated without collected evidence.</p></div><div class="note tint" style="margin-top:20px"><div class="icon">✧</div><div><h3>Make your next rehearsal intentional</h3><p>Choose one thing to practice: a clear opening, a steadier pace, or a memorable closing.</p></div></div><div class="actions">${sample?'<button class="primary" data-view="studio">Try your own rehearsal ↗</button>':'<button class="secondary" id="download">↓ Download video</button><button class="danger" id="delete">Delete session</button>'}</div></div></div>`;bind();$('#transcript-tab').onclick=()=>$('#report-transcript').scrollIntoView({behavior:'smooth'});if(!sample){activeURL=URL.createObjectURL(s.blob);$('#playback').src=activeURL;$('#download').onclick=()=>download(s);$('#delete').onclick=()=>{modal('<h2>Delete this rehearsal?</h2><p>This removes the video and associated session data from this browser. Downloaded copies remain on your device.</p><button class="danger" id="confirm-delete">Delete permanently</button>');$('#confirm-delete').onclick=()=>{const tx=db.transaction('sessions','readwrite');tx.objectStore('sessions').delete(id);tx.oncomplete=()=>{$('#dialog').close();sessions=sessions.filter(x=>x.id!==id);render('library');toast('Session and its local data deleted.')};tx.onerror=()=>toast('Deletion failed. Please retry.')}}}}
$('#privacy').onclick=()=>modal('<h2>Your practice stays in your hands.</h2><p>Videos and transcripts are stored in this browser’s IndexedDB. They are not synced between devices, and there is no account or cloud storage in this prototype.</p><p>Browser transcription is optional and may send audio to your browser provider. No recording is sent to OpenAI. Visual detection and AI coaching are unavailable.</p><p>Recordings remain until you delete them or clear browser data. Browser storage can be evicted; download anything you want to keep. There is no automatic retention worker.</p>');window.addEventListener('beforeunload',e=>{if(recorder?.state==='recording'||pending){e.preventDefault();e.returnValue=''}});render('home');
